mapper.select:
SELECT n.id, n.title, LEFT(n.content, 60) AS summary, n.type, n.is_top, n.status, COALESCE(u.real_name, u.username) AS publisher_name, n.publish_time, CASE WHEN r.id IS NULL THEN 0 ELSE 1 END AS is_read FROM notice n LEFT JOIN sys_user u ON u.id = n.publisher_id
LEFT JOIN notice_read r ON r.notice_id = n.id AND r.user_id = #{userId}
ORDER BY n.is_top DESC, n.publish_time DESC LIMIT #{startIndex}, #{dto.pageSize}

mapper.update:
UPDATE notice
SET is_top = #{isTop}
WHERE id = #{id}
